         '（胃瘻造設・高カロリー輸液）は避ける</span>。<br><span class="kw">⑤希死念慮の'
         'ある終末期患者への対応はNO.570でも問われる</span>。<br><span class="kw">'
         '⑥全人的苦痛（身体的・精神的・社会的・霊的苦痛）の観点から、痛みの緩和が他の'
