         '出題である</span>。<br><span class="kw">⑤医療資源の有限性への配慮'
         '（NO.528）は、個々の処方選択の場面にもこのように具体的に関わる</span>。<br>'
         '<span class="kw">⑥ジェネリック医薬品（後発医薬品）の選択も、同一成分・同一'
