         '<span class="kw">⑦費用対効果の評価は、個々の患者の処方選択だけでなく、'
         '医療技術評価（HTA）として医療政策レベルでも用いられる考え方である</span>。<br>'
         '<span class="kw">⑧本問は表を読み解いて数値を比較させる形式であり、まず'
         '「効果が同等な選択肢はどれとどれか」をグルーピングしてから費用を比較する'
         '手順を踏むと迷わない</span>。<br><span class="kw">⑨脂質異常症の治療は'
         '食事療法・運動療法が基本だが、効果不十分な場合に薬物療法（スタチン等）を'
