  '降圧薬を服用している。<br>生活歴：夫と2人暮らし。<br>家族歴：父が高血圧症、母が高脂血症。<br>'
  '現症：意識は清明。身長155cm、体重45kg。体温36.2℃。脈拍96/分、整。血圧126/80mmHg。呼吸数18/分。'
  'SpO2 98％（room air）。眼瞼結膜は蒼白で、眼球結膜に黄染を認めない。甲状腺腫と頸部リンパ節を'
  '触知しない。心音と呼吸音に異常を認めない。腹部は膨満しており、波動を認める。聴診で腸雑音は減弱'
